<script setup>
import { computed,ref } from 'vue';
import { cast } from '../../data/playroom.js';
import { newEscape,validateEscape,escapeAction,allLights,solveLights } from '../../room/adventureGames.js';
import { useLocalDraft } from '../../composables/useLocalDraft.js';
import { recordActivity } from '../../room/activityLog.js';
import { downloadStage } from '../../room/exportImage.js';
import RoomProp from './RoomProp.vue';
const {state,saved}=useLocalDraft('hitori-room:escape:v1',newEscape(),validateEscape),panel=ref('poster'),pin=ref(''),wires=ref(state.value.wired?['pink','blue','yellow']:['yellow','pink','blue']),message=ref('后台的灯熄了。先看看墙上的海报和地上的票根。'),hint=ref(-1),stage=ref(null),busy=ref(false),undo=ref(null);
const places=[{id:'poster',label:'墙上的海报',x:170,y:145},{id:'ticket',label:'地上的票根',x:270,y:430},{id:'case',label:'上锁的储物箱',x:555,y:415},{id:'power',label:'配电小箱',x:760,y:145},{id:'wires',label:'接线面板',x:775,y:350},{id:'desk',label:'灯光控制台',x:400,y:250},{id:'door',label:'舞台的门',x:535,y:110}];
const asset=path=>`${import.meta.env.BASE_URL}${path}`;
const inventory=computed(()=>state.value.caseOpen?[state.value.power?'保险丝 · 已装好':'一枚保险丝',state.value.wired?'连接线 · 已接好':'一束连接线','接线便签']:[]);
function inspect(id){panel.value=id;if(!state.value.inspected.includes(id))state.value.inspected.push(id);hint.value=-1;}
function act(type,value){const previous=state.value.complete,next=escapeAction(state.value,type,value);state.value=next.state;message.value=next.message;hint.value=-1;if(!previous&&next.state.complete)recordActivity('escape',`点亮 STARRY · ${next.state.moves} 次操作`,String(next.state.id));}
function help(){state.value.hints++;if(!state.value.caseOpen){message.value=state.value.hints%2?'海报给的是颜色顺序，票根给的是每种颜色的数字。把它们放在一起读。':'按粉、黄、蓝、红的顺序，数字是 2、4、1、3。';panel.value='case';}else if(!state.value.power){panel.value='power';message.value='箱子里有一枚保险丝。把它装进配电小箱。';}else if(!state.value.wired){panel.value='wires';message.value='接线便签：吉他 → 粉色；贝斯 → 蓝色；鼓 → 黄色。';}else if(state.value.lights!==allLights){panel.value='desk';hint.value=solveLights(state.value.lights)[0]??-1;message.value='试试标出的小灯。每次按下，会切换它与相邻的灯。';}else{panel.value='door';message.value='所有灯都准备好了，现在可以推开舞台的门。';}}
function reset(){undo.value=validateEscape(state.value);state.value=newEscape();panel.value='poster';pin.value='';wires.value=['yellow','pink','blue'];message.value='新的一夜，先从海报上的线索开始。';}
async function exportCard(){busy.value=true;try{await downloadStage(stage.value,'starry-light-returned.png');message.value='灯亮起来的这一刻，已经留下来了。';}catch(e){message.value=e.message;}finally{busy.value=false;}}
</script>
<template><section class="room-panel" aria-labelledby="escape-title"><div class="play-heading"><div><p class="play-eyebrow">BRING BACK THE LIGHT / 幕布后的一场小冒险</p><h2 id="escape-title">开演前，灯突然灭了。</h2><p class="room-intro">检查后台、收集线索、组合道具，修好电源与线路，再让九盏灯一起亮起来。没有倒计时。</p></div><span class="play-number" aria-hidden="true">11</span></div>
  <div class="escape-scene"><svg ref="stage" viewBox="0 0 960 600" :role="state.complete?'img':'group'" :aria-label="state.complete?'重新亮起的四人舞台':'可探索的 STARRY 后台'"><rect width="960" height="600" :fill="state.power?'#4b4257':'#292838'"/><path d="M0 420h960v180H0Z" fill="#6c5968"/><path d="M20 20h920v560H20Z" fill="none" stroke="#aa90aa"/><path d="M60 420h840M60 500h840" stroke="#a18b9b" opacity=".4"/>
    <template v-if="!state.complete"><g transform="translate(170 165)"><RoomProp kind="poster"/></g><g transform="translate(555 420) scale(1.3)"><RoomProp kind="box"/></g><g transform="translate(160 390)"><RoomProp kind="amp" :lit="state.power"/></g><rect x="730" y="95" width="90" height="120" rx="4" fill="#7c7584" stroke="#bcacbc"/><circle cx="775" cy="132" r="10" :fill="state.power?'#efd47b':'#474455'"/><path d="M755 165h40m-40 16h40" stroke="#4a4253" stroke-width="5"/>
      <path d="M467 72h136v245H467Z" fill="#363044" stroke="#a28ba0" stroke-width="4"/><text x="535" y="118" text-anchor="middle" fill="#b7a2b8" font-family="monospace" font-size="16">STAGE</text><path d="M500 275h20" stroke="#d8bd84" stroke-width="6"/>
      <rect x="322" y="228" width="156" height="86" rx="5" fill="#a091a2" stroke="#cfbdcb" stroke-width="3"/><g v-for="i in 9" :key="i"><circle :cx="351+(i-1)%3*45" :cy="247+Math.floor((i-1)/3)*25" r="7" :fill="state.wired&&(state.lights&(1<<(i-1)))?'#eed484':'#514458'"/></g><path d="M248 416h48v27h-48Z" fill="#d9b6c7"/><path d="M729 310h90v85h-90Z" fill="#a099ac"/><path d="M745 330h57M745 353h57M745 376h57" :stroke="state.wired?'#b8d4bd':'#71677d'" stroke-width="7"/>
      <g v-for="place in places" :key="place.id" :transform="`translate(${place.x},${place.y})`" class="escape-hotspot" role="button" tabindex="0" :aria-label="`检查${place.label}`" @click="inspect(place.id)" @keydown.enter.prevent="inspect(place.id)" @keydown.space.prevent="inspect(place.id)"><circle r="43" fill="transparent"/><circle cy="-42" r="16" :fill="state.inspected.includes(place.id)?'#8c6b86':'#e5c48b'"/><text y="-36" text-anchor="middle" fill="#fff5e4" font-family="sans-serif" font-size="18">{{state.inspected.includes(place.id)?'✓':'+'}}</text></g>
    </template>
    <template v-else><path d="M40 55 240 470M920 55 720 470M350 55 450 470M610 55 510 470" stroke="#e3b5d1" stroke-width="90" opacity=".12"/><g v-for="(person,index) in cast" :key="person.id"><circle :cx="180+index*200" cy="485" r="70" :fill="person.color" opacity=".25"/><image :href="asset(person.image)" :x="85+index*200" y="225" width="190" height="245" preserveAspectRatio="xMidYMid meet"/></g><text x="480" y="140" text-anchor="middle" font-family="sans-serif" font-size="54" font-weight="800" fill="#ecd08e">THE LIGHT IS BACK.</text><text x="480" y="530" text-anchor="middle" font-family="sans-serif" font-size="24" fill="#e4bdcf">幕布后的小事，也有人一起完成。</text></template>
    <text x="40" y="575" fill="#c4abc0" font-family="monospace" font-size="12" letter-spacing="3">STARRY / AN ORIGINAL LITTLE MYSTERY</text></svg></div>
  <template v-if="!state.complete"><div class="escape-places" role="group" aria-label="选择后台物品"><button v-for="place in places" :key="place.id" type="button" :aria-pressed="panel===place.id" @click="inspect(place.id)">{{state.inspected.includes(place.id)?'✓ ':''}}{{place.label}}</button></div>
    <div class="escape-clue"><template v-if="panel==='poster'"><h3>海报背面，有一句手写的提醒。</h3><p>「灯光依次走过四种颜色。第一束属于一里，接着是虹夏，再到凉，最后是喜多。」</p><div class="escape-colors"><span v-for="[color,label] in [['#dfa0bb','粉'],['#e6ca7c','黄'],['#99bdd6','蓝'],['#ce9090','红']]" :key="label" :style="{background:color}">{{label}}</span></div><p class="adventure-hint">这像是储物箱密码的读取顺序。</p></template>
      <template v-else-if="panel==='ticket'"><h3>票根上的颜色和数字。</h3><p>一张排练票的背面，印着四个小小的格子：</p><div class="escape-colors"><span v-for="[color,label] in [['#99bdd6','蓝 1'],['#ce9090','红 3'],['#dfa0bb','粉 2'],['#e6ca7c','黄 4']]" :key="label" :style="{background:color}">{{label}}</span></div><p class="adventure-hint">也许应该按别处给出的颜色顺序读它。</p></template>
      <template v-else-if="panel==='case'"><h3>{{state.caseOpen?'储物箱已经打开。':'储物箱上的四位密码。'}}</h3><template v-if="!state.caseOpen"><form @submit.prevent="act('case',pin)"><label class="room-field" for="escape-pin">转动密码锁<input id="escape-pin" v-model="pin" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" placeholder="四个数字" required></label><button type="submit" class="primary">试着打开储物箱</button></form></template><template v-else><div class="adventure-pills"><span v-for="item in inventory" :key="item">{{item}}</span></div><p>接线便签：吉他 → 粉色；贝斯 → 蓝色；鼓 → 黄色。</p></template></template>
      <template v-else-if="panel==='power'"><h3>配电小箱。</h3><p>{{state.power?'工作灯已经恢复。舞台还需要接线和灯光台。':'保险丝的位置空了，需要先从储物箱里找一枚。'}}</p><button type="button" :disabled="!state.caseOpen||state.power" @click="act('power')">{{state.power?'保险丝已装好':'装入找到的保险丝'}}</button></template>
      <template v-else-if="panel==='wires'"><h3>把三个接口接回去。</h3><p>找到的连接线足够三件乐器使用。先确认电源，再对照便签。</p><div class="room-fields"><label v-for="(name,index) in ['吉他','贝斯','鼓']" :key="name" class="room-field">{{name}}接口<select v-model="wires[index]" :disabled="state.wired"><option value="pink">粉色</option><option value="blue">蓝色</option><option value="yellow">黄色</option></select></label></div><button id="escape-wire" type="button" :disabled="!state.power||state.wired" @click="act('wires',wires)">{{state.wired?'三条线路已接好':'检查并接通线路'}}</button></template>
      <template v-else-if="panel==='desk'"><h3>九盏灯，一起亮起来。</h3><p>每按下一格，会切换它和上下左右的灯。把九格全部点亮，再去开门。</p><div class="escape-lights" role="group" aria-label="九格灯光机关"><button v-for="index in 9" :key="index" type="button" :data-light="index-1" :aria-label="`切换第${index}盏灯`" :aria-pressed="Boolean(state.lights&(1<<(index-1)))" :disabled="!state.wired" :class="{'is-hint':hint===index-1}" @click="act('light',index-1)">{{state.lights&(1<<(index-1))?'✦':'·'}}</button></div><p v-if="!state.wired" class="adventure-hint">先恢复电源并接好三条线路，灯光台才能工作。</p></template>
      <template v-else><h3>门后，是大家等待的舞台。</h3><div class="adventure-pills"><span>{{state.power?'✓':'○'}} 电源</span><span>{{state.wired?'✓':'○'}} 接线</span><span>{{state.lights===allLights?'✓':'○'}} 九盏灯</span></div><p>把所有准备接在一起，最后一步由你来完成。</p><button id="escape-door" type="button" class="primary" @click="act('door')">推开舞台的门</button></template>
    </div><div class="room-actions"><button id="escape-hint" type="button" @click="help">给一点线索</button><span class="play-footer-note">已操作 {{state.moves}} 次 · 使用 {{state.hints}} 次线索</span></div>
  </template><div v-else class="adventure-result"><span>✦</span><h3>灯亮了，可以开始了。</h3><p>{{state.moves}} 次小小的操作，接成了一次完整的开场。{{state.hints?'路上的提醒，也是一起完成这件事的一部分。':'这些线索，都被你认真接了起来。'}}</p><button type="button" class="primary" :disabled="busy" @click="exportCard">{{busy?'保存中…':'保存开灯纪念卡 ↓'}}</button></div>
  <div class="play-toolbar"><button type="button" @click="reset">开始新的一夜</button><button v-if="undo" type="button" @click="state=undo;undo=null;message='已恢复刚才的进度。'">撤销重置</button></div><p class="room-status" role="status">{{message}}</p><p class="play-footer-note">{{saved?'线索与机关进度自动保存在本机。':'当前浏览器无法保存，本次仍可继续解谜。'}} 剧情、后台场景和机关均为本站原创同人内容。</p>
</section></template>
<style scoped>.escape-scene>svg{display:block;width:100%;height:auto;border:1px solid #ad93a7}.escape-hotspot{cursor:pointer;outline:none}.escape-hotspot:focus-visible>circle:first-child{stroke:#f0d3a4;stroke-width:4}.escape-places{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}.escape-places button{font-size:12px}.escape-clue{padding:24px;background:#f1e6df;border:1px solid #d4bcc6;min-height:200px}.escape-clue h3{font-size:23px}.escape-clue p{font-size:14px}.escape-colors{display:flex;flex-wrap:wrap;gap:12px;margin:22px 0}.escape-colors>span{width:65px;height:65px;display:grid;place-items:center;color:#5b465a;font-size:19px;border:1px solid #a78b9c}.escape-clue form>button{margin-top:15px}.escape-lights{display:grid;grid-template-columns:repeat(3,minmax(0,72px));gap:10px;margin:25px 0}.escape-lights button{height:65px;background:#65516b;color:#a08ea6;font-size:27px}.escape-lights button[aria-pressed=true]{background:#ead190;color:#866032;border-color:#af8b56}.escape-lights .is-hint{outline:3px dashed #b77095;outline-offset:3px}@media(max-width:600px){.escape-clue{padding:18px}.escape-clue h3{font-size:20px}.escape-places{gap:6px}.escape-places button{font-size:11px;padding:9px}.escape-colors>span{width:52px;height:52px;font-size:16px}.escape-colors{gap:8px}}
</style>
